def retrieve(query):
    return st.session_state.retriever.invoke(query)


def retrieve_many(queries):
    """여러 질의로 검색해 중복 없이 합치기"""
    seen, docs = set(), []
    for q in queries:
        for d in retrieve(q):
            if d.page_content not in seen:
                seen.add(d.page_content)
                docs.append(d)
    return docs


