def find_korean_font():
    from matplotlib import font_manager
    for path in font_manager.findSystemFonts():
        name = os.path.basename(path).lower()
        if any(k in name for k in ["nanumgothic", "nanumbarungothic", "notosanscjk", "notosanskr",
                                    "malgun", "applegothic"]):
            return path
    return None





def roadmap_markdown(rm, is_applicant=False):
    md = [f"# {rm.get('title', '나의 학습 로드맵')}", "", rm.get("summary", ""), ""]
    for w in rm.get("weeks", []):
        stage = APPLICANT_STAGES[w["week"] - 1] if is_applicant else f"{w['week']}주차"
        md.append(f"## {stage} · {w.get('goal', '')}")
        for it in w.get("items", []):
            md.append(f"- **{it.get('topic')}**: {it.get('task')} ({it.get('hours')}h)")
        md.append("")
    if rm.get("tips"):
        md.append("## 선배 팁")
        md += [f"- {t}" for t in rm["tips"]]
    return "\n".join(md)


