def render_roadmap_strip(is_applicant):
    labels = ("지원·접수", "전형 준비", "면접·결과") if is_applicant else ("초급", "중급", "고급")
    active = LEVELS[st.session_state.user_type].index(st.session_state.level)
    stage_cards = [
        f'<span class="roadmap-stage"{" aria-current=step" if i == active else ""}>{name}</span>'
        for i, name in enumerate(labels)
    ]
    arrow = '<span class="roadmap-arrow" aria-hidden="true">→</span>'
    st.html('<div class="roadmap-strip">' + arrow.join(stage_cards) + '</div>')


