APPLICANT_STAGES = ("지원·접수", "서류·전형 준비", "면접·결과 확인")
LEARNING_STAGES = ("핵심 개념", "실습·적용", "정리·검증")


def roadmap_columns(plan, is_applicant):
    weeks = plan["weeks"]
    if is_applicant:
        return list(zip(APPLICANT_STAGES, ([week] for week in weeks)))
    split = [(len(weeks) * i) // 3 for i in range(4)]
    return [(stage, weeks[split[i]:split[i + 1]]) for i, stage in enumerate(LEARNING_STAGES)]


def roadmap_png(plan, is_applicant):
    from matplotlib.figure import Figure
    from matplotlib.font_manager import FontProperties
    from matplotlib.patches import FancyBboxPatch, FancyArrowPatch

    font = find_korean_font()
    if not font:
        raise ValueError("한글 PNG를 만들려면 기존 packages.txt의 fonts-nanum 설치가 필요합니다.")
    fp = FontProperties(fname=font)

    def lines(text, width):
        return textwrap.wrap(" ".join(str(text).split()), width=width) or [""]

    panels = []
    for stage, weeks in roadmap_columns(plan, is_applicant):
        section = []
        for week in weeks:
            label = str(week.get("goal") or stage)
            if not is_applicant:
                label = f"{week['week']}주차 · {label}"
            section.extend((line, True) for line in lines(label, 20))
            for item in week.get("items", []):
                section.extend((line, False) for line in lines(f"• {item['topic']}", 23))
            section.append(("", False))
        panels.append((stage, section))

    height = 2.45 + 0.24 * max(len(section) for _, section in panels)
    fig = Figure(figsize=(12, height), dpi=145, facecolor="#F8F3E8")
    ax = fig.add_axes([0, 0, 1, 1])
    ax.set(xlim=(0, 12), ylim=(0, height))
    ax.axis("off")
    ax.text(0.42, height - 0.46, "지원자 맞춤형 전형 로드맵" if is_applicant else "교육생 맞춤형 학습 로드맵",
            fontproperties=fp, fontsize=18, color="#29241C", va="center", weight="bold")
    ax.text(0.43, height - 0.82, "AIVLE ROADMAP AI · 백서 기반 준비 제안",
            fontproperties=fp, fontsize=9.5, color="#62594F", va="center")

    accents = ("#CBE9E0", "#A5D9CC", "#81C8B7")
    for index, (stage, section) in enumerate(panels):
        x = 0.42 + index * 3.84
        ax.add_patch(FancyBboxPatch(
            (x, 0.36), 3.48, height - 1.42, boxstyle="round,pad=0.02,rounding_size=0.15",
            linewidth=1, edgecolor="#DED5C4", facecolor="#FFFCF5",
        ))
        ax.add_patch(FancyBboxPatch(
            (x + 0.12, height - 1.68), 3.24, 0.43, boxstyle="round,pad=0.02,rounding_size=0.10",
            linewidth=0, facecolor=accents[index],
        ))
        ax.text(x + 1.74, height - 1.47, stage, fontproperties=fp, fontsize=12.5,
                color="#193D33", ha="center", va="center", weight="bold")
        if index < len(panels) - 1:
            ax.add_patch(FancyArrowPatch(
                (x + 3.49, height - 1.45), (x + 3.82, height - 1.45),
                arrowstyle="-|>", color="#8C8070", mutation_scale=13,
            ))
        for row, (line, heading) in enumerate(section):
            ax.text(x + 0.24, height - 2.02 - 0.24 * row, line, fontproperties=fp,
                    fontsize=10.7 if heading else 9.6, color="#302820" if heading else "#52483E",
                    va="center", weight="bold" if heading else "normal")
    buffer = io.BytesIO()
    fig.savefig(buffer, format="png", facecolor=fig.get_facecolor())
    return buffer.getvalue()


def make_roadmap(goal, count, is_applicant, track):
    prep_type = "지원 전형 준비 단계" if is_applicant else "학습 주차"
    queries = (
        ["모집 지원 자격 접수 선발 전형 면접", f"{track} {goal} 지원 준비"] if is_applicant
        else [f"{goal} {st.session_state.level} 실습 프로젝트", "주차별 학습 계획 선배 후기 학습 전략"]
    )
    docs = retrieve_many(queries)
    result = llm_json(
        task_system(f"개인 맞춤형 {prep_type} 로드맵을 작성합니다. 공고에 없는 전형이나 날짜를 단정하지 마세요. "
                    "제공된 문서에 근거한 준비 계획으로 제안하세요. 각 항목 이름은 이미지에 들어가도록 간단히 쓰세요."),
        f"[목표] {goal}\n[트랙] {track}\n[개수] {count}\n"
        + (f"[단계] {', '.join(APPLICANT_STAGES)}\n" if is_applicant else f"[난이도] {st.session_state.level}\n")
        + f"[문서]\n{format_docs_with_page(docs)}\n\n"
        + f"weeks에 {count}개의 {prep_type}을 순서대로 작성하고 단계마다 items를 2~3개 쓰세요. "
        'JSON 형식은 {"title":"제목","summary":"요약","weeks":[{"week":1,"goal":"목표",'
        '"items":[{"topic":"짧은 할 일","task":"구체적 설명","hours":1}]}],"tips":["백서 근거 (p.N)"]}입니다.',
    )
    steps = result.get("weeks")
    if not isinstance(steps, list) or len(steps) != count:
        raise ValueError("요청한 단계 수와 생성 결과가 맞지 않아요. 다시 생성해 주세요.")
    for index, step in enumerate(steps, 1):
        if not isinstance(step, dict) or not isinstance(step.get("items"), list) or not step["items"]:
            raise ValueError("로드맵의 실행 항목이 비어 있어요. 다시 생성해 주세요.")
        if any(not isinstance(item, dict) or not item.get("topic") for item in step["items"]):
            raise ValueError("로드맵의 실행 항목을 읽을 수 없어요. 다시 생성해 주세요.")
        step["week"] = index
    return result, docs


def render_roadmap(is_applicant):
    state = st.session_state
    title = "지원자 맞춤형 전형 로드맵" if is_applicant else "교육생 맞춤형 학습 로드맵"
    if state.get("roadmap_image"):
        heading, export = st.columns([5, 1], vertical_alignment="center")
        heading.subheader(title)
        export.download_button("PNG 내보내기", state.roadmap_image,
                               file_name="my_aivle_roadmap.png", mime="image/png", width="stretch")
    else:
        st.subheader(title)
    with st.expander("로드맵 만들기·수정", expanded=state.roadmap is None), st.form("roadmap_form"):
        left, right = st.columns([1.9, 1])
        goal = left.text_input("지원 목표" if is_applicant else "학습 목표",
                               placeholder="예: DX 트랙 지원 준비" if is_applicant else "예: RAG 챗봇 설계와 구현",
                               max_chars=150)
        if is_applicant:
            track = right.selectbox("관심 트랙", ["미정", "AI 개발자", "DX 컨설턴트"])
            count = 3
        else:
            count = right.selectbox("학습 기간", [3, 4, 6, 8], index=1, format_func=lambda n: f"{n}주")
            track = "미선택"
        build = st.form_submit_button("로드맵 만들기", type="primary")

    if build:
        goal = goal.strip() or ("지원 전형 준비하기" if is_applicant else "RAG 챗봇 실습과 결과 검증")
        try:
            with st.spinner("백서에 기반한 로드맵을 만드는 중…"):
                plan, docs = make_roadmap(goal, count, is_applicant, track)
            try:
                png = roadmap_png(plan, is_applicant)
                png_error = ""
            except (ValueError, ImportError) as exc:
                png, png_error = None, str(exc)
            state.update(roadmap=plan, roadmap_docs=docs, roadmap_image=png, roadmap_image_error=png_error,
                         roadmap_version=state.get("roadmap_version", 0) + 1, done={})
            st.rerun()
        except Exception as exc:
            st.warning(f"로드맵을 만들지 못했어요. {exc}")

    plan = state.roadmap
    if not plan:
        return None, None
    png = state.get("roadmap_image")
    if png:
        st.image(png, width="stretch", caption="백서에 기반한 개인 준비 제안")
    elif state.get("roadmap_image_error"):
        st.caption(state.roadmap_image_error)
    if plan.get("summary"):
        st.caption(plan["summary"])

    all_items = []
    with st.expander("세부 계획과 진행률", expanded=not png):
        for stage, weeks in roadmap_columns(plan, is_applicant):
            st.markdown(f"**{stage}**")
            for week in weeks:
                if not is_applicant:
                    st.markdown(f"**{week['week']}주차** · {week.get('goal', '')}")
                for i, item in enumerate(week["items"]):
                    key = f"done_{state.get('roadmap_version', 0)}_{week['week']}_{i}"
                    state.done[key] = st.checkbox(str(item["topic"]), key=key, help=item.get("task"))
                    all_items.append(item)
        completed = sum(bool(value) for value in state.done.values())
        st.progress(completed / max(len(all_items), 1), text=f"진행률 {completed}/{len(all_items)}")
        if plan.get("tips"):
            for tip in plan["tips"]:
                st.markdown(f"- {tip}")
        show_sources(state.roadmap_docs, key="roadmap_sources")
        st.download_button("계획 상세 저장", roadmap_markdown(plan, is_applicant), file_name="my_aivle_roadmap.md")
        if not is_applicant and all_items:
            topic = st.selectbox("복습할 학습 항목", [str(item["topic"]) for item in all_items])
            action = "quiz" if st.button("선택한 항목으로 복습 퀴즈 만들기") else None
            st.button("이 항목의 실무 활용 질문하기", on_click=queue_chat,
                      args=(f"{topic}을(를) 실무에서 어떻게 활용하나요?",))
            return topic, action
    return None, None





def render_quiz(topic, action):
    st.subheader("AI 퀴즈 · 복습")
    quiz_topic = st.text_input("퀴즈 주제", value=topic or (st.session_state.mat_info.get("topics") or ["RAG 개념과 구현"])[0],
                               key=f"quiz_topic_{topic}")
    q2, q3 = st.columns(2)
    diff = q2.selectbox("난이도", ["초급", "중급", "고급"],
                        index=["초급", "중급", "고급"].index(st.session_state.level)
                        if st.session_state.level in ["초급", "중급", "고급"] else 0)
    n_q = q3.selectbox("문항 수", [3, 5], index=0)
    quiz_src = st.radio("출제 범위", ["백서", "내 학습 자료"], horizontal=True,
                        index=1 if st.session_state.mat_store is not None else 0,
                        disabled=st.session_state.mat_store is None,
                        help="왼쪽 자료 관리에서 자료를 등록하면 내 교안·실습 파일로 퀴즈를 낼 수 있어요.")

    if st.button("퀴즈 만들기", type="primary", width="stretch") or action == "quiz":
        with st.spinner("선택한 자료에서 문제를 만드는 중..."):
            if quiz_src == "내 학습 자료" and st.session_state.mat_store is not None:
                docs = st.session_state.mat_store.similarity_search(quiz_topic, k=6)
                ctx = format_materials(docs)
            else:
                docs = retrieve_many([quiz_topic, f"{quiz_topic} 개념 정리"])
                ctx = format_docs_with_page(docs)
            quiz = llm_json(
                task_system(f"'{quiz_topic}'에 대해 {diff} 난이도의 4지선다 복습 퀴즈를 출제합니다. "
                            "초급은 개념 확인, 중급은 적용·비교, 고급은 원인 분석·평가 문제로 냅니다. "
                            "반드시 [문서] 내용으로 정답을 확정할 수 있는 문제만 냅니다."),
                f"[문서]\n{ctx}\n\n"
                f'{n_q}문항을 {{"questions": [{{"q": "문제", "options": ["보기1","보기2","보기3","보기4"], '
                '"answer": 0, "explanation": "해설 (p.N)"}]}} 형식으로. answer는 정답 보기의 인덱스(0~3).',
                temperature=0.6)
        st.session_state.quiz = {"topic": quiz_topic, "diff": diff, "items": quiz.get("questions", []),
                                 "id": datetime.datetime.now().strftime("%H%M%S%f")}
        st.session_state.quiz_result = None

    quiz = st.session_state.quiz
    if quiz and quiz["items"]:
        with st.form("quiz_form"):
            st.markdown(f"**주제: {quiz['topic']} · 난이도: {quiz['diff']}**")
            picks = []
            for i, item in enumerate(quiz["items"]):
                picks.append(st.radio(f"Q{i + 1}. {item['q']}", range(len(item["options"])),
                                      format_func=lambda k, it=item: it["options"][k],
                                      index=None, key=f"quiz_{i}_{quiz['id']}"))
            graded = st.form_submit_button("✅ 채점하기", type="primary")
        if graded:
            st.session_state.quiz_result = picks
        answers = st.session_state.quiz_result
        answered = sum(pick is not None for pick in answers) if answers is not None else 0
        st.progress(answered / len(quiz["items"]), text=f"채점한 문항 {answered}/{len(quiz['items'])}")

        if st.session_state.quiz_result is not None:
            picks = st.session_state.quiz_result
            score = sum(1 for p, it in zip(picks, quiz["items"]) if p == it.get("answer"))
            total = len(quiz["items"])
            rate = score / total
            st.metric("점수", f"{score} / {total}", f"{rate:.0%}")
            if rate >= 0.8:
                st.success(f"🎉 {quiz['diff']} 수준을 잘 이해하고 있어요! 다음 난이도에 도전해 보세요.")
            elif rate >= 0.5:
                st.warning("👍 기본은 잡혔어요. 틀린 문제의 해설과 근거 페이지를 복습한 뒤 다시 풀어 보세요.")
            else:
                st.error("💪 한 단계 낮은 난이도로 개념부터 다시 다져 보세요. 꾸준함이 실력이 됩니다!")
            for i, (p, it) in enumerate(zip(picks, quiz["items"])):
                ok = p == it.get("answer")
                with st.expander(f"{'⭕' if ok else '❌'} Q{i + 1}. {it['q']}", expanded=not ok):
                    st.markdown(f"- 내 답: {it['options'][p] if p is not None else '미응답'}")
                    st.markdown(f"- 정답: **{it['options'][it.get('answer', 0)]}**")
                    st.markdown(f"- 해설: {it.get('explanation', '')}")


def render_inquiry(s, state_key):
    # 공식 문의문 자동 작성 (기능 11)
    if st.button("공식 문의문 자동 작성", key=f"{state_key}_action"):
        with st.spinner("문의문을 작성하는 중..."):
            text = "".join(llm_stream(
                task_system("담당 매니저에게 보낼 공손하고 간결한 공식 문의문을 작성합니다. "
                            "구성: 제목 / 인사 / 소속([기수]·[반]·[이름]) / 상황(날짜·시간 포함) / "
                            "문의 사항(번호 목록) / 첨부 예정 증빙 / 마무리 인사. "
                            "개인정보는 [ ] 빈칸으로 두고, 비밀번호·인증번호는 절대 넣지 않습니다."),
                f"[상황 유형] {s['category']}\n[상황] {s['situation']}\n[안내 내용]\n{s['text']}"))
        st.session_state[state_key] = text
    if st.session_state.get(state_key):
        edited = st.text_area("문의문 (수정 후 복사해 사용하세요)", st.session_state[state_key], height=210,
                              key=f"{state_key}_draft_{hash(st.session_state[state_key])}")
        st.download_button("문의문 저장(.txt)", edited, file_name="aivle_inquiry.txt", key=f"{state_key}_download")







render_app()
